patch:
--- a/src/core/parse.js
+++ b/src/core/parse.js
@@ -1,1 +1,4 @@
-module.exports = (input) => Number(input);
+module.exports = (input) => {
+  const value = Number(input);
+  return Number.isFinite(value) ? { ok: true, value } : { ok: false };
+};
--- a/src/api/handler.js
+++ b/src/api/handler.js
@@ -1,2 +1,5 @@
-const parse = require("src/core/parse.js");
-module.exports = (query) => ({ status: 200, body: parse(query.limit) });
+const parse = require("src/core/parse.js");
+module.exports = (query) => {
+  const parsed = parse(query.limit);
+  return parsed.ok ? { status: 200, body: parsed.value } : { status: 400, body: "invalid limit" };
+};

